import{c as e,Q as a,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"How to keep AI spend flat while token usage grows exponentially","description":"","frontmatter":{"url":"https://x.com/brian_armstrong/status/2070670644577280109","title":"How to keep AI spend flat while token usage grows exponentially","author":"Brian Armstrong","archived":"2026-07-02T00:00:00.000Z","category":"deep-application","handle":"@brian_armstrong","published":"2026-06-26T00:00:00.000Z","score":"7.6/10","stats":"6049❤ · 728 retweets","tags":["prompt-caching","cost-optimization","model-routing","coinbase"],"type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-07-02-@brian_armstrong-280109.md","filePath":"research/tweets/2026-07-02-@brian_armstrong-280109.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-07-02-@brian_armstrong-280109.md"};function s(i,t,d,p,g,l){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="how-to-keep-ai-spend-flat-while-token-usage-grows-exponentially-—-brian-armstrong" tabindex="-1">How to keep AI spend flat while token usage grows exponentially — @brian_armstrong <a class="header-anchor" href="#how-to-keep-ai-spend-flat-while-token-usage-grows-exponentially-—-brian-armstrong" aria-label="Permalink to &quot;How to keep AI spend flat while token usage grows exponentially — @brian_armstrong&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/brian_armstrong/status/2070670644577280109" target="_blank" rel="noreferrer">https://x.com/brian_armstrong/status/2070670644577280109</a><strong>類別</strong>：deep-application <strong>統計</strong>：6049❤ · 728 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>How to keep AI spend flat while token usage grows exponentially: Not with friction and spend alerts. With better defaults, routing, and caching.</p><p><strong>Better Defaults（非 Usage Caps）</strong> — 工程師仍可自由選擇任何模型，但預設值很重要。Coinbase 正在實驗將內部 LibreChat 部署預設導向開源權重模型（GLM 5.2、Kimi 2.7），而非直接預設 frontier 模型。</p><p><strong>Task-based Routing</strong> — 依任務複雜度路由到適當成本層級的模型，而非統一使用最貴的 frontier 模型處理所有請求。</p><p><strong>Caching（第三槓桿）</strong> — Cache miss 是最容易讓成本失控的原因。Coinbase 針對 LibreChat 部署優化快取策略後，cache hit rate 從 5% 提升到 60%（12 倍改善），代表多數 AI 查詢能以接近零成本返回已儲存結果，在 token 使用量持續成長的同時讓整體 AI 支出降低近 50%。</p><p><strong>Lean Context + Spend Visibility</strong> — 完整五槓桿框架另包含精簡 context 與將支出透明度與預期影響掛鉤，讓工程師對成本有感知但不設限制其模型選擇自由。</p><p>核心結論：AI 成本控制不需要限制存取，而是需要投資在讓成本與任務複雜度匹配的基礎設施（gateway + 預設值 + 路由 + 快取）。</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>直接呼應 workspace <code>context-management.md</code> Prompt Caching Static First 原則；cache hit rate 5%→60% 為具體可仿效的優化目標</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>五槓桿框架（defaults/routing/caching/context/visibility）為既有概念的系統化整合，非全新方法論</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>有具體數字（cache hit rate、~50% 成本降低），但為企業自報數據非第三方驗證，社群推文上限 6 分</td></tr><tr><td>D. 技術深度 (15%)</td><td>5/10</td><td>推文層級摘要，缺乏實作細節（如快取 key 設計、TTL 策略）</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用任何大規模 LLM 部署，非 Coinbase 特化情境</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.85/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule（補充 context-management.md 快取命中率優化實例） <strong>理由</strong>：Coinbase 案例可作為 Prompt Caching Static First 原則的量化 ground truth（cache hit rate 目標值）</p>',14)])])}const m=e(o,[["render",s]]);export{c as __pageData,m as default};
